package com.learnagent.digest;
import jakarta.persistence.*;import java.time.*;import java.util.UUID;
@Entity@Table(name="daily_digests")public class DailyDigest{@Id private UUID id;@Column(name="digest_date",nullable=false,unique=true)private LocalDate digestDate;@Column(name="course_id")private UUID courseId;@Column(nullable=false)private String topic;@Column(name="markdown_path",nullable=false)private String markdownPath;@Column(nullable=false,columnDefinition="text")private String summary;@Column(name="created_at",nullable=false)private Instant createdAt;protected DailyDigest(){}public DailyDigest(LocalDate date,UUID course,String topic,String path,String summary){id=UUID.randomUUID();digestDate=date;courseId=course;this.topic=topic;markdownPath=path;this.summary=summary;createdAt=Instant.now();}public UUID getId(){return id;}public LocalDate getDigestDate(){return digestDate;}public UUID getCourseId(){return courseId;}public String getTopic(){return topic;}public String getMarkdownPath(){return markdownPath;}public String getSummary(){return summary;}public Instant getCreatedAt(){return createdAt;}}
